struct Msg {
    Msg() = default;
    Msg(const Msg&) { std::cout << "copy\n"; }   // move not declared: rvalues use copy
};

Msg decode(bool first) {
    Msg a, b;
    if (first) return a;
    return b;
}

int main() {
    Msg m = decode(true);   // prints "copy"
    (void)m;
}
```

