    std::pmr::vector<int> v(res);
    for (int i = 0; i < 100; ++i) v.push_back(i);
    return v;
}

int main() {
    std::pmr::monotonic_buffer_resource arena;   // declared before v: outlives it
    auto v = load(&arena);
    std::cout << v[99] << '\n';                  // 99
}
