```cpp
#include <iostream>
#include <memory>

struct Data {
    int x = 1, y = 2;
    ~Data() { std::cout << "~Data\n"; }
};

int main() {
    auto p = std::make_shared<Data>();
    std::shared_ptr<int> q(p, &p->y);     // aliasing
    std::cout << *q << ' ' << q.use_count() << '\n';   // 2 2
    p.reset();
    std::cout << *q << ' ' << q.use_count() << '\n';   // 2 1, Data alive
    q.reset();                                          // ~Data
