#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <malloc.h>
#include <string>
#include <vector>

long rss_kb() {
    std::ifstream f("/proc/self/status");
    std::string line;
    while (std::getline(f, line))
        if (line.rfind("VmRSS:", 0) == 0) return std::stol(line.substr(6));
    return -1;
}

int main() {
    std::cout << "start            RSS " << rss_kb() << " kB\n";
    std::vector<char*> blocks;
    for (int i = 0; i < 200000; ++i) {
        char* p = static_cast<char*>(std::malloc(256));
        std::memset(p, 1, 256);
        blocks.push_back(p);
    }
    std::cout << "200k x 256 B     RSS " << rss_kb() << " kB\n";
    for (std::size_t i = 0; i + 1 < blocks.size(); ++i) std::free(blocks[i]);
    std::cout << "freed all but 1  RSS " << rss_kb() << " kB\n";
    malloc_trim(0);                                  // glibc extension
    std::cout << "malloc_trim(0)   RSS " << rss_kb() << " kB\n";
    std::free(blocks.back());

    void* big = std::malloc(64 << 20);               // above mmap threshold
    std::cout << "malloc 64 MiB    RSS " << rss_kb() << " kB (not touched)\n";
    std::memset(big, 1, 64 << 20);                   // page faults happen here
    std::cout << "touched          RSS " << rss_kb() << " kB\n";
    std::free(big);                                  // munmap: returned at once
    std::cout << "free 64 MiB      RSS " << rss_kb() << " kB\n";
}

interview_qa.explanation:
- `delete` also runs a destructor that `malloc` never paired with a constructor.
- A replaced global `operator new` (jemalloc, counting allocator) can use a completely different heap.
- Correct mixed use:
```cpp
void* raw = std::malloc(sizeof(Order));
Order* p = ::new (raw) Order(1);
std::destroy_at(p);
std::free(raw);
```
- For implicit-lifetime types (plain structs, scalars), C++20 says `malloc` implicitly creates the object, so `static_cast<Header*>(std::malloc(sizeof(Header)))` is usable directly. A `std::string` is not implicit-lifetime: it needs a real constructor call.
- ❌ Common wrong answer: "It works on Linux because `new` calls `malloc`." It works until the allocator or the type changes.
- ✅ What a strong answer adds: C APIs that return `malloc`ed memory should be wrapped in `std::unique_ptr<T, decltype(&std::free)>` (or a stateless deleter) so the right function is always used.

