#include <vector>

struct Order {
    int id = 0;
    ~Order() { std::cout << "~Order " << id << '\n'; }
};

int main() {
    std::vector<Order> batch(3);
    for (int i = 0; i < 3; ++i) batch[i].id = i;
}   // ~Order 0, ~Order 1, ~Order 2 (elements destroyed in order of index in libstdc++)
```

